# Nicht konforme Geraete
# Berechtigungen: DeviceManagementManagedDevices.Read.All
$all = @(Invoke-GraphRequestAll -Token $Token -Endpoint '/deviceManagement/managedDevices?$select=deviceName,userPrincipalName,complianceState,operatingSystem,osVersion,lastSyncDateTime')
$dev = @($all | Where-Object { $_.complianceState -in 'noncompliant', 'inGracePeriod' })
Write-Host "$($dev.Count) Geraete nicht konform" -ForegroundColor $(if ($dev.Count) { 'Yellow' } else { 'Green' })
foreach ($d in $dev) {
    [pscustomobject]@{
        Geraet = $d.deviceName; Benutzer = $d.userPrincipalName; Status = $d.complianceState
        System = "$($d.operatingSystem) $($d.osVersion)"; LetzterSync = ([datetime]$d.lastSyncDateTime).ToLocalTime()
    }
}

# Inaktive Benutzer
# Berechtigungen: User.Read.All, AuditLog.Read.All (signInActivity braucht Entra ID P1)
# @param Tage|int|Keine Anmeldung seit Tagen|90
# @param NurLizenziert|bool|Nur Benutzer mit Lizenz|true

$grenze = (Get-Date).AddDays(-$Tage)
$users = @(Invoke-GraphRequestAll -Token $Token -Endpoint '/users?$select=displayName,userPrincipalName,accountEnabled,createdDateTime,signInActivity,assignedLicenses,jobTitle,department')
$users = @($users | Where-Object { $_.accountEnabled })
if ($NurLizenziert) { $users = @($users | Where-Object { @($_.assignedLicenses).Count -gt 0 }) }

foreach ($u in $users) {
    $last = $null
    if ($u.signInActivity -and $u.signInActivity.lastSignInDateTime) { $last = [datetime]$u.signInActivity.lastSignInDateTime }
    if ($last -and $last -ge $grenze) { continue }
    if (-not $last -and [datetime]$u.createdDateTime -ge $grenze) { continue }   # neu angelegt
    [pscustomobject]@{
        Name           = $u.displayName
        UPN            = $u.userPrincipalName
        LetzteAnmeldung = $(if ($last) { $last.ToLocalTime() } else { 'nie' })
        Erstellt       = ([datetime]$u.createdDateTime).ToLocalTime()
        Rolle          = $u.jobTitle
        Klasse         = $u.department
        Lizenzen       = @($u.assignedLicenses).Count
    }
}

# MFA-Registrierung
# Berechtigungen: AuditLog.Read.All (Bericht userRegistrationDetails, Entra ID P1)
# @param NurOhneMfa|bool|Nur Benutzer OHNE MFA|true
# @param NurAdmins|bool|Nur Administratoren|false

$r = @(Invoke-GraphRequestAll -Token $Token -Endpoint '/reports/authenticationMethods/userRegistrationDetails')
if ($NurOhneMfa) { $r = @($r | Where-Object { -not $_.isMfaRegistered }) }
if ($NurAdmins)  { $r = @($r | Where-Object { $_.isAdmin }) }
Write-Host "$($r.Count) Eintraege" -ForegroundColor Cyan
foreach ($x in $r) {
    [pscustomobject]@{
        UPN = $x.userPrincipalName; Name = $x.userDisplayName; Admin = $x.isAdmin
        MfaRegistriert = $x.isMfaRegistered; MfaFaehig = $x.isMfaCapable
        Methoden = (@($x.methodsRegistered) -join ', '); Standard = $x.defaultMfaMethod
    }
}

# Gast-Konten
# Berechtigungen: User.Read.All
$g = @(Invoke-GraphRequestAll -Token $Token -Endpoint "/users?`$filter=userType eq 'Guest'&`$select=displayName,mail,userPrincipalName,createdDateTime,externalUserState")
Write-Host "$($g.Count) Gaeste" -ForegroundColor Cyan
foreach ($u in $g) {
    [pscustomobject]@{
        Name = $u.displayName; Mail = $u.mail; Status = $u.externalUserState
        Erstellt = ([datetime]$u.createdDateTime).ToLocalTime()
    }
}

# Autopilot-Geraete
# Berechtigungen: DeviceManagementServiceConfig.Read.All
# @param GroupTag|string|Nur dieser Group Tag (leer = alle)|

$ap = @(Invoke-GraphRequestAll -Token $Token -Endpoint '/deviceManagement/windowsAutopilotDeviceIdentities')
if ($GroupTag) { $ap = @($ap | Where-Object { $_.groupTag -eq $GroupTag }) }
Write-Host "$($ap.Count) Autopilot-Geraete" -ForegroundColor Cyan
foreach ($a in $ap) {
    [pscustomobject]@{
        Seriennr = $a.serialNumber; GroupTag = $a.groupTag; Hersteller = $a.manufacturer; Modell = $a.model
        Status = $a.enrollmentState
        ZuletztGemeldet = $(if ($a.lastContactedDateTime -and ([datetime]$a.lastContactedDateTime).Year -gt 2000) { ([datetime]$a.lastContactedDateTime).ToLocalTime() } else { '' })
    }
}

# Ablaufende Secrets und Zertifikate von App-Registrierungen
# Berechtigungen: Application.Read.All
# @param Tage|int|Ablauf innerhalb von Tagen|60

$grenze = (Get-Date).AddDays($Tage)
$apps = @(Invoke-GraphRequestAll -Token $Token -Endpoint '/applications?$select=displayName,appId,passwordCredentials,keyCredentials')
foreach ($a in $apps) {
    $creds = @($a.passwordCredentials | ForEach-Object { @{ Art = 'Secret'; Name = $_.displayName; Ende = $_.endDateTime } }) +
             @($a.keyCredentials | ForEach-Object { @{ Art = 'Zertifikat'; Name = $_.displayName; Ende = $_.endDateTime } })
    foreach ($c in $creds) {
        if (-not $c.Ende) { continue }
        $ende = ([datetime]$c.Ende).ToLocalTime()
        if ($ende -gt $grenze) { continue }
        [pscustomobject]@{
            App = $a.displayName; AppId = $a.appId; Art = $c.Art; Bezeichnung = $c.Name
            GueltigBis = $ende; Tage = [int]($ende - (Get-Date)).TotalDays
        }
    }
}

# Intune-Geraete synchronisieren
# Berechtigungen: DeviceManagementManagedDevices.Read.All, DeviceManagementManagedDevices.PrivilegedOperations.All
# @param Geraete|string|Geraetenamen (Komma-getrennt)|
# @param DryRun|bool|Nur anzeigen (DryRun)|true

$namen = @("$Geraete" -split '[,;]' | ForEach-Object { $_.Trim() } | Where-Object { $_ })
if (-not $namen.Count) { Write-Warning 'Bitte oben im Feld Geraetenamen eintragen.'; return }
foreach ($n in $namen) {
    $d = @(Invoke-GraphRequestAll -Token $Token -Endpoint "/deviceManagement/managedDevices?`$filter=deviceName eq '$($n -replace "'", "''")'&`$select=id,deviceName,lastSyncDateTime")
    if (-not $d.Count) { Write-Warning "$n : nicht gefunden"; continue }
    foreach ($x in $d) {
        if ($DryRun) { Write-Host "[DryRun] wuerde synchronisieren: $($x.deviceName) (letzter Sync $([datetime]$x.lastSyncDateTime))" -ForegroundColor Yellow; continue }
        $r = Invoke-GraphRequestWithRetry -Token $Token -Method POST -Endpoint "/deviceManagement/managedDevices/$($x.id)/syncDevice"
        if ($r -and $r.PSObject.Properties['IsError'] -and $r.IsError) { Write-Host "$($x.deviceName): Fehler $($r.StatusCode) $($r.ErrorMessage)" -ForegroundColor Red }
        else { Write-Host "$($x.deviceName): Sync gesendet" -ForegroundColor Green }
    }
}

# Mitglieder einer Gruppe
# Berechtigungen: Group.Read.All (oder GroupMember.Read.All), User.Read.All
# @param Gruppe|string|Gruppenname (Anfang)|

if (-not $Gruppe) { Write-Warning 'Bitte oben den Gruppennamen eintragen.'; return }
$g = @(Invoke-GraphRequestAll -Token $Token -Endpoint "/groups?`$filter=startswith(displayName,'$($Gruppe -replace "'", "''")')&`$select=id,displayName")
if (-not $g.Count) { Write-Warning "Keine Gruppe beginnt mit '$Gruppe'"; return }
foreach ($grp in $g) {
    $m = @(Invoke-GraphRequestAll -Token $Token -Endpoint "/groups/$($grp.id)/members?`$select=displayName,userPrincipalName,deviceId")
    Write-Host "$($grp.displayName): $($m.Count) Mitglieder" -ForegroundColor Cyan
    foreach ($x in $m) {
        [pscustomobject]@{
            Gruppe = $grp.displayName
            Typ    = ("$($x.'@odata.type')" -replace '#microsoft.graph.', '')
            Name   = $x.displayName
            UPN    = $x.userPrincipalName
        }
    }
}

# Kurzbeschreibung: was macht das Skript?
# Berechtigungen: ...
# @param DryRun|bool|Nur anzeigen (DryRun)|true
# @param Tage|int|Zeitraum in Tagen|30
#
# Verfuegbar: $Token, $TenantKey, $Settings, Get-HUToken, Invoke-GraphRequest, Invoke-GraphRequestAll,
#             Invoke-GraphRequestWithRetry - und die Parameter oben als Variablen ($DryRun, $Tage).
# Objekte ([pscustomobject]) erscheinen im Knopf "Tabelle" (Filter, CSV, Excel).
# Mehrere Tenants: oben "Mehrere" - das Skript laeuft je Tenant einmal.

$daten = @(Invoke-GraphRequestAll -Token $Token -Endpoint '/users?$select=id,displayName,userPrincipalName&$top=999')
Write-Host "$($daten.Count) Eintraege in $TenantKey" -ForegroundColor Cyan

foreach ($d in $daten | Select-Object -First 20) {
    if ($DryRun) {
        # nur anzeigen
    } else {
        # hier aendern - z. B. Invoke-GraphRequestWithRetry -Token $Token -Method PATCH -Endpoint "/users/$($d.id)" -Body @{ ... }
    }
    [pscustomobject]@{ Name = $d.displayName; UPN = $d.userPrincipalName }
}
